before:
Complete local Go example; the app itself does not execute it:
```go
package main
import ("fmt")
type Reader interface { Read() int }
type Counter struct { N int }
func (c *Counter) Read() int { return c.N }
func show(r Reader) { fmt.Println(r.Read()) }
func main() {
 c := Counter{N: 7}
 show(&c)
}
```

